\label{peano} Let $T\in\mathcal{M}$ and let $\rho:[0,1]\to\{|z|\leq \|T\|_{\infty}\}$ be a Peano curve.\footnote{A continuous surjective mapping $[0,1]\to[0,1]^2$ was first constructed by Peano \cite{Peano}. See, for example, \cite{Man} for details. We may take the ball rather than the square since they are homeomorphic.}
\begin{enumerate}[(a)]
\item Set $q_t$ to be the Haagerup--Schultz projection for $T$ associated to the Borel set $\rho([0,t]).$
Then $q_t$ is increasing in $t$.
Since $\tau(q_t)=\nu_T(\rho([0,t])$, we have $q_t=\wedge_{t'>t}q_{t'}$;
i.e., $q_t$ is strong-operator-topology continuous from the right in $t$.
\item Set $\mathcal{D}$ to be the von Neumann algebra generated by $\{q_t\mid t\in[0,1]\}.$
\item For every $n\geq0,$ set $\mathcal{D}_n$ to be the algebra generated by $q_{k/2^n},$ $0\leq k\leq 2^n.$
\end{enumerate}
For technical convenience, we will assume that the Brown measure of $T$ has no atom at $\rho(0)$ (i.e. $\nu_T(\rho(0))=0$). This ensures $q_0=0$ and it can always be arranged by modification of $\rho,$ if necessary.

 By Theorem \ref{thm:HS}, the projections $q_{k/2^n},$ $0\leq k\leq 2^n,$ are increasing in $k.$ Letting $f^n_k=q_{(k+1)/2^n}-q_{k/2^n}$ for $0\le k<2^n,$ we have
\begin{equation}\label{eq:EDn}
{\rm Exp}_{\mathcal{D}_n}(T)=\sum_{\substack{0\le k<2^n \\ f^n_k\ne0}}\frac{\tau(f^n_kTf^n_k)}{\tau(f^n_k)}f^n_k.
\end{equation}
By Construction \ref{peano} and Theorem \ref{thm:HS}, when $f^n_k\ne0,$ the Brown measure of $f^n_kTf^n_k$ in $f^n_k\mathcal{M}f^n_k$ is supported in $\rho([0,\frac{k+1}{2^n}])\backslash \rho([0,\frac{k}{2^n}])$ (which is a subset of $\rho((\frac{k}{2^n},\frac{k+1}{2^n}])$). It follows from Theorem \ref{thm:HS} \eqref{hsc},\eqref{hsd} combined with Brown's analogue of Lidskii's theorem \cite{Brown} that
\begin{equation}\label{trace partitioning}
\frac{\tau(f^n_kTf^n_k)}{\tau(f^n_k)}=\frac{\int_{\rho([0,\frac{k+1}{2^n}])\backslash \rho([0,\frac{k}{2^n}])}zd\nu_T(z)}{\nu_T(\rho([0,\frac{k+1}{2^n}])\backslash \rho([0,\frac{k}{2^n}]))}\in\overline{\rm conv}(\rho((\frac{k}{2^n},\frac{k+1}{2^n}])).
\end{equation}
Now take $m>n$ and note that
$$f^n_k=\sum_{j=2^{m-n}k}^{2^{m-n}(k+1)-1}f_j^m.$$
For $2^{m-n}k\leq j< 2^{m-n}(k+1)$ such that $f^m_j\ne0$, we have
$$\frac{\tau(f^m_jTf^m_j)}{\tau(f^m_j)}\in\overline{\rm conv}(\rho((\frac{j}{2^m},\frac{j+1}{2^m}]))\subset\overline{\rm conv}(\rho((\frac{k}{2^n},\frac{k+1}{2^n}])).$$
It follows that
\begin{equation}\label{eq:EDnDm}
\|{\rm Exp}_{\mathcal{D}_n}(T)-{\rm Exp}_{\mathcal{D}_m}(T)\|_{\infty}\le\max_{0\le k<2^n}\operatorname{diam}\big(\rho((\frac{k}{2^n},\frac {k+1}{2^n}])\big)\le\omega(2^{-n})
\end{equation}
and this upper bound tends to $0$ as $n\to\infty.$
By Lemma \ref{exp limit lemma}, ${\rm Exp}_{\mathcal{D}_n}(T)$ converges in strong operator topology to ${\rm Exp}_{\mathcal{D}}(T).$ By the above estimate, it is Cauchy in the uniform norm, and, therefore, converges in that norm to ${\rm Exp}_{\mathcal{D}}(T).$ Now letting $m\to\infty$ in \eqref{eq:EDnDm} completes the proof of the lemma.

\label{det convergence} Let $T\in\mathcal{M}$ and let $q_t$,  $\mathcal{D}$ and $\mathcal{D}_n$ be as in Construction \ref{peano}. For every $\lambda\in\mathbb{C},$ and $\varepsilon>0$, we have
\begin{equation}\label{eq:det convergence}
\lim_{n\to\infty}\log\Delta(|{\rm Exp}_{\mathcal{D}_n}(T)-\lambda|^2+\varepsilon)=\int_{\mathbb{C}}\log(|z-\lambda|^2+\varepsilon)d\nu_T(z).
\end{equation}

